      size > limit ->
        raise PetstoreClient.Errors.ResponseTooLargeError, status_code: status, limit: limit

      state == :finished ->
        IO.iodata_to_binary([acc, output])

      produced == 0 ->
        :erlang.error(:data_error)

      true ->
        inflate_within(z, :zlib.safeInflate(z, []), [acc, output], size, bound)
    end
  end

  # Reads a buffered body under `max_response_bytes`: the chunks are counted as
  # they arrive, before any decompression, and the read stops (the connection is
  # dropped, not drained) as soon as the count passes the limit or the declared
  # Content-Length already does.
  defp bounded_into(limit) do
    fn
      {:data, data}, {req, resp} ->
        size = Req.Response.get_private(resp, :sdk_body_size, 0) + byte_size(data)

        if size > limit or declared_length(resp) > limit do
          {:halt, {req, Req.Response.put_private(resp, :sdk_too_large, true)}}
        else
          resp = Req.Response.put_private(resp, :sdk_body_size, size)
          {:cont, {req, %{resp | body: (resp.body || "") <> data}}}
        end

      _other, acc ->
        {:cont, acc}
    end
  end

  defp declared_length(resp) do
    with [value | _] <- Req.Response.get_header(resp, "content-length"),
         {length, ""} <- Integer.parse(String.trim(value)) do
      length
    else
      _ -> 0
    end
  end

  # A hop read under `max_response_bytes` that passed it raises
  # ResponseTooLargeError with the real status and headers. A body that came back
  # whole (a custom adapter that does not stream) is checked by its size.
  defp ensure_within_limit!(response, nil), do: response

  defp ensure_within_limit!(response, limit) do
    body = response.body

    if Req.Response.get_private(response, :sdk_too_large, false) or
         (is_binary(body) and byte_size(body) > limit) do
      raise PetstoreClient.Errors.ResponseTooLargeError,
        status_code: response.status,
        limit: limit,
        response_headers: normalize_headers(response.headers)
    end

    response
  end

  # `br` is only advertised in Accept-Encoding when the optional :brotli NIF is
  # loaded, so a server should never send it otherwise; guard anyway.
  defp brotli_body(body, status, limit) do
    if Code.ensure_loaded?(:brotli) do
      # Called through apply/3: :brotli is an optional dependency, so it is
      # not known when this module is compiled. A `mod.fun(arg)` call on a
      # variable module is constant-folded by the compiler and warns that the
      # module is undefined, which `--warnings-as-errors` turns into a failure.
      decoder = apply(:brotli_decoder, :new, [])
      brotli_within(decoder, body, [], 0, {status, limit})
    else
      raise PetstoreClient.Errors.ApiError,
        message: "Received a br-encoded response but the br library is unavailable",
        status_code: status
    end
  end

  # Makes the same :brotli_nif calls as :brotli_decoder.stream/2, but counts the
  # output each time the decoder hands it over (at most one window, a few MiB),
  # so under a limit decoding stops with ResponseTooLargeError as soon as the
  # output passes it instead of after the whole body is decoded. A stream that
  # ends before its last meta-block, or is corrupt, fails like any other
  # undecodable body.
  defp brotli_within(decoder, input, acc, size, {status, _limit} = bound) do
    case apply(:brotli_nif, :decoder_decompress_stream, [decoder, input]) do
      :ok ->
        {acc, _size} = brotli_take(decoder, acc, size, bound)
        IO.iodata_to_binary(acc)

      {:more_output, remaining} ->
        {acc, size} = brotli_take(decoder, acc, size, bound)
        rest = binary_part(input, byte_size(input) - remaining, remaining)
        brotli_within(decoder, rest, acc, size, bound)

      _ ->
        raise PetstoreClient.Errors.ApiError,
          message: "Failed to decompress br response body",
          status_code: status
    end
  end

  defp brotli_take(decoder, acc, size, {status, limit} = bound) do
    case apply(:brotli_nif, :decoder_take_output, [decoder]) do
      <<>> ->
        {acc, size}

      output ->
        size = size + byte_size(output)

        if is_integer(limit) and size > limit do
          raise PetstoreClient.Errors.ResponseTooLargeError, status_code: status, limit: limit
        end

        brotli_take(decoder, [acc, output], size, bound)
    end
  end

  # `zstd` is only advertised in Accept-Encoding when Erlang/OTP ships the
  # :zstd module (OTP 28 and later), so a server should never send it
  # otherwise; guard anyway. Under a limit the body is decoded 16 input bytes
  # at a time (a few bytes of zstd can stand for megabytes) and the decoding
  # stops with ResponseTooLargeError as soon as the output passes the limit.
  defp zstd_body(body, status, limit) do
    if Code.ensure_loaded?(:zstd) do
      try do
        # Called through apply/3 so the module still compiles on an older OTP.
        if is_integer(limit) do
          {:ok, context} = apply(:zstd, :context, [:decompress])
          zstd_within(context, body, [], 0, {status, limit})
        else
          :zstd |> apply(:decompress, [body]) |> IO.iodata_to_binary()
        end
      rescue
        e in PetstoreClient.Errors.ResponseTooLargeError ->
          reraise e, __STACKTRACE__

        e ->
          reraise PetstoreClient.Errors.ApiError,
                  [
                    message: "Failed to decompress zstd response body: #{Exception.message(e)}",
                    status_code: status,
                    cause: e
                  ],
                  __STACKTRACE__
      end
    else
      raise PetstoreClient.Errors.ApiError,
        message: "Received a zstd-encoded response but the zstd library is unavailable",
        status_code: status
    end
  end

  defp zstd_within(context, input, acc, size, {status, limit} = bound) do
    {piece, rest} =
      if byte_size(input) > 16,
        do: {binary_part(input, 0, 16), binary_part(input, 16, byte_size(input) - 16)},
        else: {input, <<>>}

    {output, rest, done?} =
      case rest do
        <<>> ->
          case apply(:zstd, :finish, [context, piece]) do
            {:done, output} -> {output, <<>>, true}
            {:continue, remainder, output} -> {output, remainder, false}
            # A stream that ends before its last frame gives nothing more.
            {:continue, output} -> {zstd_progress!(output), <<>>, false}
          end

        _ ->
          case apply(:zstd, :stream, [context, piece]) do
            {:continue, remainder, output} -> {output, remainder <> rest, false}
            {:continue, output} -> {output, rest, false}
          end
      end

    size = size + IO.iodata_length(output)

    cond do
      size > limit ->
        raise PetstoreClient.Errors.ResponseTooLargeError, status_code: status, limit: limit

      done? ->
        IO.iodata_to_binary([acc, output])

      true ->
        zstd_within(context, rest, [acc, output], size, bound)
    end
  end

  defp zstd_progress!(output) do
    if IO.iodata_length(output) == 0, do: :erlang.error(:data_error)
    output
  end

  @doc """
  Decode a response body to a binary string honouring the `charset` directive
  parsed from the `Content-Type` header. Defaults to UTF-8 when no charset is
  provided. A byte that is invalid in UTF-8 is replaced with U+FFFD, one per
  bad byte. Falls back to the raw bytes (treated as UTF-8) when the charset is
  unknown or conversion fails -- never raises.

  This is exposed for use by error-body decoding paths as well.
  """
  @spec decode_text_body(binary(), String.t()) :: binary()
  def decode_text_body(body, content_type) when is_binary(body) do
    charset = parse_charset(content_type)

    case charset do
      nil ->
        body

      "utf-8" ->
        String.replace_invalid(body)

      "utf8" ->
        String.replace_invalid(body)

      "us-ascii" ->
        body

      "ascii" ->
        body

      other ->
        {encoding, payload} = charset_encoding(other, body)

        case encoding do
          nil ->
            body

          :windows_1252 ->
            decode_windows_1252(payload)

          atom ->
            try do
              case :unicode.characters_to_binary(payload, atom, :utf8) do
                result when is_binary(result) -> result
                _ -> body
              end
            rescue
              _ -> body
            catch
              _, _ -> body
            end
        end
    end
  end

  def decode_text_body(body, _content_type), do: body

  defp parse_charset(content_type) when is_binary(content_type) do
    content_type
    |> String.split(";")
    |> Enum.drop(1)
    |> Enum.map(&String.trim/1)
    |> Enum.find_value(fn part ->
      case String.split(part, "=", parts: 2) do
        [k, v] ->
          if String.downcase(String.trim(k)) == "charset" do
            v
            |> String.trim()
            |> String.trim("\"")
            |> String.downcase()
          else
            nil
          end

        _ ->
          nil
      end
    end)
  end

  defp parse_charset(_), do: nil

  @utf16_little {:utf16, :little}
  @utf16_big {:utf16, :big}

  # A bare `utf-16` label honours a leading byte order mark (and drops it), and
  # is big-endian only without one, as RFC 2781 prescribes.
  defp charset_encoding(label, <<0xFF, 0xFE, rest::binary>>) when label in ["utf-16", "utf16"],
    do: {@utf16_little, rest}

  defp charset_encoding(label, <<0xFE, 0xFF, rest::binary>>) when label in ["utf-16", "utf16"],
    do: {@utf16_big, rest}

  defp charset_encoding(label, body), do: {charset_to_atom(label), body}

  # The C1 range of windows-1252 (0x80..0x9F); the five undefined bytes map to
  # the matching control code point. Every other byte is its latin1 code point.
  @windows_1252_c1 {0x20AC, 0x81, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030,
                    0x0160, 0x2039, 0x0152, 0x8D, 0x017D, 0x8F, 0x90, 0x2018, 0x2019, 0x201C,
                    0x201D, 0x2022, 0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x9D,
                    0x017E, 0x0178}

  defp decode_windows_1252(body) do
    for <<byte <- body>>, into: "" do
      codepoint = if byte in 0x80..0x9F, do: elem(@windows_1252_c1, byte - 0x80), else: byte
      <<codepoint::utf8>>
    end
  end

  defp charset_to_atom("windows-1252"), do: :windows_1252
  defp charset_to_atom("cp1252"), do: :windows_1252
  defp charset_to_atom("iso-8859-1"), do: :latin1
  defp charset_to_atom("latin1"), do: :latin1
  defp charset_to_atom("latin-1"), do: :latin1
  defp charset_to_atom("utf-16"), do: :utf16
  defp charset_to_atom("utf16"), do: :utf16
  defp charset_to_atom("utf-16le"), do: {:utf16, :little}
  defp charset_to_atom("utf-16be"), do: {:utf16, :big}
  defp charset_to_atom("utf-32"), do: :utf32
  defp charset_to_atom("utf32"), do: :utf32
  defp charset_to_atom("utf-32le"), do: {:utf32, :little}
  defp charset_to_atom("utf-32be"), do: {:utf32, :big}
  defp charset_to_atom(_), do: nil

  @doc false
  def send_request(method, url, headers, body) do
    new() |> send_request(method, url, headers, body)
  end

  @doc """
  Marks this client closed. Idempotent.

  Req/Finch owns a globally supervised connection pool, so there is no
  socket to tear down here. A call that starts after `close/1` raises a typed
  SDK error instead of silently proceeding (uniform use-after-close contract);
  an operation already in flight finishes, except that the streams still open
  are cancelled: their next read raises the same error. What the SDK started for the client
  (the authenticators' processes) is released by whoever wins
  `claim_release/1`: `close/1` of the client when nothing is in flight, else
  the last operation to finish.
  """
  @impl PetstoreClient.ApiClient
  @spec close(t()) :: :ok
  def close(%__MODULE__{closed: nil}), do: :ok

  def close(%__MODULE__{closed: state, owners: owners}) do
    :ok = set_closed(state)
    PetstoreClient.StreamBody.cancel_all(owners)
  end

  defp set_closed(state) do
    current = :atomics.get(state, 1)

    cond do
      band(current, 1) == 1 -> :ok
      :atomics.compare_exchange(state, 1, current, bor(current, 1)) == :ok -> :ok
      true -> set_closed(state)
    end
  end

  @doc false
  # Admits one operation: it counts as in flight until `finish_request/1`. A
  # closed client refuses with the canonical error, so a new call fails and an
  # admitted one cannot be cut off. Any other transport (a custom `api_client`)
  # is not counted and admits everything.
  @spec begin_request(term()) :: :ok
  def begin_request(%__MODULE__{closed: state} = client) when state != nil do
    current = :atomics.get(state, 1)

    cond do
      band(current, 1) == 1 -> raise RuntimeError, @closed_message
      :atomics.compare_exchange(state, 1, current, current + 2) == :ok -> :ok
      true -> begin_request(client)
    end
  end

  def begin_request(_client), do: :ok

  @doc false
  # Ends one admitted operation.
  @spec finish_request(term()) :: :ok
  def finish_request(%__MODULE__{closed: state} = client) when state != nil do
    current = :atomics.get(state, 1)

    cond do
      current < 2 -> :ok
      :atomics.compare_exchange(state, 1, current, current - 2) == :ok -> :ok
      true -> finish_request(client)
    end
  end

  def finish_request(_client), do: :ok

  @doc false
  # True for exactly one caller, once the client is closed and nothing is in
  # flight: that caller releases what the SDK started for the client. False
  # while it is open, while an operation is in flight and after the release.
  @spec claim_release(term()) :: boolean()
  def claim_release(%__MODULE__{closed: state}) when state != nil do
    :atomics.get(state, 1) == 1 and :atomics.compare_exchange(state, 2, 0, 1) == :ok
  end

  def claim_release(_client), do: false

  @doc """
  The static portion of the Req options: everything that depends on
  `TransportOptions` and is fixed for the lifetime of the ApiClient. The
  per-request options (method, url, headers, body) are merged at the call
  site via `Req.request!/2`.

  Public so a test can prove the single `:timeout` option arms every deadline
  the stack has rather than only one of them.
  """
  @spec request_options(PetstoreClient.TransportOptions.t()) :: keyword()
  def request_options(opts) do
    # Always disable Req's auto-redirect; we follow Location
    # manually in send_request so we can strip Authorization / Cookie /
    # Proxy-Authorization on cross-origin hops.
    # `raw: true` disables Req's built-in body decoding AND decompression. We
    # decompress explicitly in send_request keyed on the Content-Encoding
    # response header (see decompress_body/2). Req 0.5.x patch releases differ
    # in whether they auto-decompress when body decoding is disabled, which
    # left gzip bodies undecoded nondeterministically across CI runs; doing it
    # ourselves is version-independent.
    # `retry: false` disables Req's default retry of transient failures: a
    # transport error surfaces once, as NetworkError, like every other SDK.
    req_opts = [
      raw: true,
      redirect: false,
      retry: false
    ]

    _ = opts.follow_redirects

    # `:timeout` arms every deadline this client is allowed to set:
    # `:receive_timeout` is the idle timer between chunks, the connect deadline
    # below is the TCP/TLS handshake, and the total budget is enforced by the
    # Task in send_request. The pool checkout keeps Req's own default: its
    # `:pool_timeout` lives under `:finch`, and Req refuses `:finch` together
    # with the `:connect_options` this client needs for the proxy, the CA
    # bundle and that connect deadline. A blown pool checkout is still an
    # expired deadline, so transport_error/1 classifies it as
    # NetworkTimeoutError rather than letting it arrive as a NetworkError.
    req_opts =
      if opts.timeout do
        Keyword.put(req_opts, :receive_timeout, opts.timeout)
      else
        req_opts
      end

    req_opts =
      if opts.max_redirects do
        Keyword.put(req_opts, :max_redirects, opts.max_redirects)
      else
        req_opts
      end

    req_opts =
      if opts.proxy do
        proxy_uri = URI.parse(opts.proxy)

        {scheme, default_port} =
          if proxy_uri.scheme == "https", do: {:https, 443}, else: {:http, 80}

        proxy =
          {scheme, String.to_charlist(proxy_uri.host), proxy_uri.port || default_port,
           [hostname: proxy_uri.host]}

        # Credentials in the proxy URL travel as Proxy-Authorization to the
        # proxy only: on the CONNECT request for an https:// target, and on
        # each forwarded request for an http:// target. They never reach the
        # target server.
        proxy_headers =
          case build_proxy_auth_header(opts.proxy) do
            nil -> []
            header -> [{"proxy-authorization", header}]
          end

        Keyword.put(req_opts, :connect_options, proxy: proxy, proxy_headers: proxy_headers)
      else
        req_opts
      end

    req_opts =
      cond do
        !opts.verify_ssl ->
          connect_opts = Keyword.get(req_opts, :connect_options, [])

          transport_opts =
            Keyword.get(connect_opts, :transport_opts, [])
            |> Keyword.put(:verify, :verify_none)

          connect_opts = Keyword.put(connect_opts, :transport_opts, transport_opts)
          Keyword.put(req_opts, :connect_options, connect_opts)

        opts.ca_cert_path ->
          connect_opts = Keyword.get(req_opts, :connect_options, [])

          transport_opts =
            Keyword.get(connect_opts, :transport_opts, [])
            |> Keyword.put(:verify, :verify_peer)
            |> Keyword.put(:cacertfile, String.to_charlist(opts.ca_cert_path))

          connect_opts = Keyword.put(connect_opts, :transport_opts, transport_opts)
          Keyword.put(req_opts, :connect_options, connect_opts)

        true ->
          req_opts
      end

    req_opts =
      if opts.timeout do
        connect_opts = Keyword.get(req_opts, :connect_options, [])
        connect_opts = Keyword.put(connect_opts, :timeout, opts.timeout)
        Keyword.put(req_opts, :connect_options, connect_opts)
      else
        req_opts
      end

    req_opts
  end

  # Credential-bearing headers that must be stripped
  # before following a cross-origin redirect. Includes the static OAuth/cookie
  # set plus any apiKey-in-header names declared by the OpenAPI security schemes
  # so a malicious 302 can't exfiltrate a tenant's API key by sending the client
  # at an attacker host. Names are compared case-insensitively (lower-cased here
  # to match `String.downcase/1` of the request header key at the call site).
  @sensitive_redirect_headers [
    "authorization",
    "cookie",
    "proxy-authorization",
    "x-api-key",
    "x-internal-key"
  ]

  # Mint forwards an http:// target through the connection to the proxy and
  # reads only the proxy tuple's options for it, and Finch receives
  # synchronously, so that connection must be passive. An https:// target
  # tunnels through CONNECT, which needs the proxy connection left active.
  #
  # A per-call timeout replaces the transport's connect and idle deadlines for
  # this request, so a call may be given more time than the client default.
  defp proxy_request_options(client, url, call_timeout) do
    connect_options = Map.get(client.base_req.options, :connect_options, [])

    {timeout_options, connect_options} =
      if call_timeout,
        do:
          {[receive_timeout: call_timeout], Keyword.put(connect_options, :timeout, call_timeout)},
        else: {[], connect_options}

    case {URI.parse(url).scheme, Keyword.get(connect_options, :proxy)} do
      {"http", {scheme, host, port, proxy_opts}} ->
        proxy = {scheme, host, port, Keyword.put(proxy_opts, :mode, :passive)}
        timeout_options ++ [connect_options: Keyword.put(connect_options, :proxy, proxy)]

      _ ->
        if call_timeout, do: timeout_options ++ [connect_options: connect_options], else: []
    end
  end

  # One request of the redirect loop. A buffered hop reads the whole response
  # (Req's response); a streaming hop returns at the headers, with the body not
  # read, as `%{status: integer, headers: map, stream: StreamBody.t()}`.
  defp send_hop(client, method, url, headers, body, deadline, call_timeout, :buffered) do
    {body, headers} = hop_body(body, headers)
    limit = client.transport_options.max_response_bytes
    bounded = if limit, do: [into: bounded_into(limit)], else: []

    # Catch inside the task so it always returns a tagged value and never
    # crashes the linked caller: Task.async links, so an uncaught raise
    # would take down this process before Task.yield could observe it.
    req_fun = fn ->
      try do
        {:ok,
         Req.request!(
           client.base_req,
           [
             method: method,
             url: url,
             headers: Enum.map(headers, fn {k, v} -> {k, v} end),
             body: body
           ] ++ bounded ++ proxy_request_options(client, url, call_timeout)
         )}
      rescue
        exception -> {:raised, exception, __STACKTRACE__}
      end
    end

    deadline
    |> run_hop(req_fun, client, call_timeout)
    |> ensure_within_limit!(limit)
  end

  # The streaming hop: the request runs in a process of its own (see
  # `StreamBody`), and the call waits for the response headers only, so the
  # deadline stops there. The socket's own receive timeout is lifted because
  # the deadline (for the headers) and the idle timeout (for the body) are
  # enforced by the SDK and one socket setting cannot be both.
  defp send_hop(
         client,
         method,
         url,
         headers,
         body,
         deadline,
         call_timeout,
         {:stream, idle_timeout}
       ) do
    {body, headers} = hop_body(body, headers)

    options =
      [
        method: method,
        url: url,
        headers: Enum.map(headers, fn {k, v} -> {k, v} end),
        body: body
      ] ++
        Keyword.put(proxy_request_options(client, url, call_timeout), :receive_timeout, :infinity)

    spec = %{
      req: client.base_req,
      options: options,
      method: method,
      idle_timeout: idle_timeout,
      owners: client.owners
    }

    case PetstoreClient.StreamBody.open(spec, deadline) do
      {:ok, status, response_headers, stream} ->
        %{status: status, headers: response_headers, stream: stream}

      {:error, exception} ->
        raise exception

      :timeout ->
        raise PetstoreClient.Errors.NetworkTimeoutError,
          message:
            "request exceeded total timeout of #{call_timeout || client.transport_options.timeout}ms",
          status_code: 0
    end
  end

  # Runs one buffered request within what is left of the deadline.
  defp run_hop(deadline, req_fun, client, call_timeout) do
    case deadline do
      nil ->
        case req_fun.() do
          {:ok, result} -> result
          {:raised, exception, stacktrace} -> reraise(exception, stacktrace)
        end

      _deadline ->
        total = max(deadline - System.monotonic_time(:millisecond), 0)

        # Req/Finch's :receive_timeout is per-chunk inactivity
        # (it resets on every received packet), so a slow-trickle response
        # can run arbitrarily long without tripping it. Enforce a hard
        # end-to-end wall-clock budget by running the call in a Task and
        # shutting it down if it overruns the configured timeout.
        task = Task.async(req_fun)

        case Task.yield(task, total) || Task.shutdown(task) do
          {:ok, {:ok, result}} ->
            result

          {:ok, {:raised, exception, stacktrace}} ->
            reraise(exception, stacktrace)

          nil ->
            raise PetstoreClient.Errors.NetworkTimeoutError,
              message:
                "request exceeded total timeout of #{call_timeout || client.transport_options.timeout}ms",
              status_code: 0
        end
    end
  end

  # A BodySource is opened for each hop, so a replay reads it again from the start. A body that
  # is not in memory is sent as it is read: with its length as `Content-Length` when that is
  # known, else chunked (no length header at all).
  defp hop_body(%PetstoreClient.BodySource{} = source, headers) do
    case PetstoreClient.BodySource.open(source) do
      {bytes, _length} when is_binary(bytes) ->
        {bytes, headers}

      {stream, length} ->
        headers =
          Map.reject(headers, fn {name, _value} ->
            String.downcase(to_string(name)) in ["content-length", "transfer-encoding"]
          end)

        headers =
          if is_integer(length),
            do: Map.put(headers, "Content-Length", Integer.to_string(length)),
            else: headers

        {stream, headers}
    end
  end

  defp hop_body(body, headers), do: {body, headers}

  # A hop whose response is not the one the caller gets (a redirect that is
  # followed or refused) lets go of its connection first.
  defp discard_hop(%{stream: stream}), do: PetstoreClient.StreamBody.close(stream)
  defp discard_hop(_buffered), do: :ok

  defp do_request_with_redirects(
         client,
         method,
         url,
         headers,
         body,
         max_redirects,
         {no_redirect, given_deadline, call_timeout, mode}
       ) do
    # One end-to-end budget for the whole call: the deadline is fixed here and
    # every redirect hop spends what is left of it, never a fresh timeout. A
    # deadline handed in by the caller (a retry of the same operation) is kept.
    deadline =
      case {given_deadline, call_timeout || client.transport_options.timeout} do
        {nil, nil} -> nil
        {nil, total} -> System.monotonic_time(:millisecond) + total
        {given, _total} -> given
      end

    do_request_with_redirects(
      client,
      method,
      url,
      url,
      headers,
      body,
      {max_redirects, 0},
      {no_redirect, deadline, call_timeout, mode}
    )
  end

  defp do_request_with_redirects(
         client,
         method,
         url,
         orig_url,
         headers,
         body,
         {max, hops},
         {no_redirect, deadline, call_timeout, mode}
       ) do
    response = send_hop(client, method, url, headers, body, deadline, call_timeout, mode)

    if not no_redirect and client.transport_options.follow_redirects and
         redirect_status?(response.status) do
      case redirect_location(response.headers) do
        nil ->
          response

        location ->
          next_url = resolve_url(url, location)

          cond do
            next_url == nil ->
              response

            not http_scheme?(next_url) ->
              # Refuse to follow a redirect to a non-http(s) scheme
              # (e.g. file:, javascript:, data:). Silently returning the
              # 3xx would hide a potential SSRF / local-file-read vector;
              # surface it as a typed SDK error instead.
              discard_hop(response)

              raise PetstoreClient.Errors.ApiError,
                message:
                  "Refusing to follow redirect to non-HTTP(S) URL: #{redact_url(next_url)}",
                status_code: response.status

            true ->
              cross_origin = not same_origin?(orig_url, next_url)

              # A single use body was read to its end by the first hop. It is
              # never buffered to make a replay possible, so a redirect that
              # keeps the method (and so the body) is refused.
              if next_method_keeps_body?(response.status, method) and
                   PetstoreClient.BodySource.single_use?(body) do
                discard_hop(response)

                raise PetstoreClient.Errors.ApiError,
                  message: "Refusing to replay a streamed request body",
                  status_code: response.status
              end

              # Refuse to replay a request body across a transport
              # downgrade (HTTPS -> HTTP). A 307/308 normally preserves the
              # method and body, but doing so would leak any sensitive payload
              # the caller sent under TLS onto a plaintext wire. Abort the
              # redirect chain instead of silently replaying.
              #
              # Anchor on the CURRENT hop (url, whose body would be replayed),
              # not the original request (orig_url): an http -> https -> http
              # chain downgrades on the final hop even though the first request
              # was already http, which an orig_url anchor would miss.
              if refuse_body_replay?(response.status, url, next_url, body) do
                discard_hop(response)

                raise PetstoreClient.Errors.ApiError,
                  message: replay_refusal_message(url, next_url),
                  status_code: response.status
              end

              # Pick follow-up method+body per RFC 9110 section 15.4: 307 and
              # 308 never change them, 303 turns everything but HEAD into GET,
              # and 301 and 302 turn only POST into GET.
              next_method = redirect_method(response.status, method)
              next_body = if next_method == method, do: body, else: nil

              stripped_headers =
                if cross_origin do
                  headers
                  |> strip_sensitive_headers()
                  |> drop_default_headers(client.transport_options.default_headers)
                else
                  headers
                end

              next_headers =
                if next_body == nil do
                  strip_body_headers(stripped_headers)
                else
                  stripped_headers
                end

              # Exceeding the redirect cap is a response that arrived but
              # cannot be used: an ApiError with the redirect's real status.
              if hops + 1 > max do
                discard_hop(response)

                raise PetstoreClient.Errors.ApiError,
                  message: "Too many redirects (exceeded #{max})",
                  status_code: response.status
              end

              discard_hop(response)

              do_request_with_redirects(
                client,
                next_method,
                next_url,
                orig_url,
                next_headers,
                next_body,
                {max, hops + 1},
                {no_redirect, deadline, call_timeout, mode}
              )
          end
      end
    else
      response
    end
  end

  defp redirect_status?(code) when code in [301, 302, 303, 307, 308], do: true
  defp redirect_status?(_), do: false

  defp redirect_location(headers) when is_map(headers) do
    Enum.find_value(headers, fn {k, v} ->
      if String.downcase(to_string(k)) == "location" do
        case v do
          [first | _] -> first
          val when is_binary(val) -> val
          _ -> nil
        end
      end
    end)
  end

  defp redirect_location(headers) when is_list(headers) do
    Enum.find_value(headers, fn {k, v} ->
      if String.downcase(to_string(k)) == "location" do
        to_string(v)
      end
    end)
  end

  defp redirect_location(_), do: nil

  defp http_scheme?(url) do
    case URI.parse(url) do
      %URI{scheme: s} when s in ["http", "https"] -> true
      _ -> false
    end
  end

  # A Location that cannot be resolved, or that names an http(s) URL the
  # transport could not send (`http://[bad`), resolves to nil: the 3xx comes
  # back as the response, never as an exception (D71).
  defp resolve_url(base, location) do
    resolved =
      case URI.parse(location) do
        %URI{scheme: s} when not is_nil(s) -> location
        _ -> base |> URI.merge(location) |> URI.to_string()
      end

    if sendable_url?(resolved), do: resolved, else: nil
  rescue
    _ -> nil
  end

  # Only an http(s) URL is checked here: any other scheme is refused by name
  # in the caller.
  defp sendable_url?(url) do
    case URI.parse(url) do
      %URI{scheme: scheme} when scheme in ["http", "https"] ->
        match?({:ok, %URI{host: host}} when is_binary(host) and host != "", URI.new(url))

      _ ->
        true
    end
  end

  @doc false
  # Whether two URLs share scheme, host and port, with an implicit default port
  # equal to the explicit one (https://h and https://h:443 are one origin).
  @spec same_origin?(String.t(), String.t()) :: boolean()
  def same_origin?(a, b) do
    pa = URI.parse(a)
    pb = URI.parse(b)

    same_scheme =
      pa.scheme && pb.scheme && String.downcase(pa.scheme) == String.downcase(pb.scheme)

    same_host = pa.host && pb.host && String.downcase(pa.host) == String.downcase(pb.host)
    port_a = pa.port || default_port(pa.scheme)
    port_b = pb.port || default_port(pb.scheme)
    same_scheme == true and same_host == true and port_a == port_b
  end

  @doc false
  # Detect an HTTPS -> HTTP scheme downgrade between the original
  # request URL and the next redirect hop. Returns true only when the
  # original was `https` and the next is `http` (case-insensitive); same-
  # scheme and HTTP -> HTTPS upgrades are safe.
  @spec downgrade?(String.t(), String.t()) :: boolean()
  def downgrade?(orig, next_url) do
    o = URI.parse(orig)
    n = URI.parse(next_url)

    os = if o.scheme, do: String.downcase(o.scheme), else: nil
    ns = if n.scheme, do: String.downcase(n.scheme), else: nil
    os == "https" and ns == "http"
  end

  @doc false
  # The method a redirect with `status` is followed with (RFC 9110 section
  # 15.4): 307 and 308 keep it; 303 turns every method except HEAD into GET;
  # 301 and 302 turn only POST into GET. A method that changes drops the body.
  @spec redirect_method(integer(), atom()) :: atom()
  def redirect_method(status, method) do
    name = method |> to_string() |> String.upcase()

    cond do
      status == 303 and name != "HEAD" -> :get
      status in [301, 302] and name == "POST" -> :get
      true -> method
    end
  end

  defp next_method_keeps_body?(status, method), do: redirect_method(status, method) == method

  @doc false
  # Whether following a redirect would replay a request body over an HTTPS ->
  # HTTP downgrade. 301 and 302 are refused too, since a method they keep (PUT,
  # for example) replays the body; 303 is never refused because it becomes a GET.
  # Only a real body can leak: nil is no body, and so is the empty string the
  # client substitutes on POST/PUT/PATCH to force an explicit `Content-Length: 0`.
  @spec refuse_body_replay?(integer(), String.t(), String.t(), term()) :: boolean()
  def refuse_body_replay?(status, url, next_url, body) do
    status in [301, 302, 307, 308] and body not in [nil, ""] and downgrade?(url, next_url)
  end

  @doc false
  # The D16 message of a refused body replay; both URLs lose their query,
  # userinfo and fragment, so a credential in a URL never reaches the text.
  @spec replay_refusal_message(String.t(), String.t()) :: String.t()
  def replay_refusal_message(url, next_url) do
    "Refusing to replay request body across HTTPS->HTTP redirect: " <>
      "#{redact_url(url)} -> #{redact_url(next_url)}"
  end

  defp default_port("https"), do: 443
  defp default_port("http"), do: 80
  defp default_port(_), do: nil

  # The static list plus the redaction rule (S15): a header whose name contains
  # key, token or secret carries a credential, wherever it came from (a
  # default header, a custom authenticator), so it does not follow a
  # cross-origin hop either.
  defp strip_sensitive_headers(headers) when is_map(headers) do
    Enum.reject(headers, fn {k, _v} ->
      lowered = String.downcase(to_string(k))

      lowered in @sensitive_redirect_headers or
        String.contains?(lowered, ["key", "token", "secret"])
    end)
    |> Map.new()
  end

  # The transport's default headers are meant for the API origin only, so a
  # redirect to another origin does not carry them (matched by name, any case).
  defp drop_default_headers(headers, defaults) when is_map(headers) do
    names = defaults |> Map.keys() |> Enum.map(&String.downcase(to_string(&1))) |> MapSet.new()

    headers
    |> Enum.reject(fn {k, _v} -> MapSet.member?(names, String.downcase(to_string(k))) end)
    |> Map.new()
  end

  defp strip_body_headers(headers) when is_map(headers) do
    Enum.reject(headers, fn {k, _v} ->
      String.downcase(to_string(k)) in ["content-type", "content-length"]
    end)
    |> Map.new()
  end

  defp prepare_body(nil, headers) do
    {nil, Map.reject(headers, fn {k, _v} -> String.downcase(to_string(k)) == "content-type" end)}
  end

  defp prepare_body(body, headers) when is_map(body) and not is_struct(body) do
    multipart_body(body, headers)
  end

  # An ordered list of `{name, value}` parts (the order the spec declares the
  # form fields in) is a multipart body too.
  defp prepare_body(body, headers) when is_list(body), do: multipart_body(body, headers)

  defp prepare_body(body, headers), do: {body, headers}

  # A declared multipart subtype (`multipart/mixed`, `multipart/related`) is
  # kept and gains the boundary; anything else is sent as multipart/form-data.
  defp multipart_body(body, headers) do
    boundary = generate_uuid()

    {declared, headers} =
      Enum.reduce(headers, {nil, %{}}, fn {k, v}, {found, acc} ->
        if String.downcase(to_string(k)) == "content-type",
          do: {v, acc},
          else: {found, Map.put(acc, k, v)}
      end)

    subtype =
      if is_binary(declared) and declared =~ ~r/\Amultipart\/[A-Za-z0-9!#$&^_.+-]+\z/i,
        do: String.downcase(declared),
        else: "multipart/form-data"

    {build_multipart_body(body, boundary),
     Map.put(headers, "Content-Type", "#{subtype}; boundary=#{boundary}")}
  end

  @doc false
  # Public for testability: this is the exact serializer `prepare_body/2`
  # uses for multipart request bodies. Exposed so the generated test suite
  # can assert on per-part Content-Type derivation and field name
  # preservation without reaching through the transport layer.
  def build_multipart_body(form_parts, boundary) do
    parts =
      Enum.flat_map(form_parts, fn {name, value} ->
        {value, encoding} = part_encoding(value)
        items = if is_list(value), do: value, else: [value]

        Enum.map(items, fn item ->
          name |> multipart_part(item) |> apply_part_encoding(encoding) |> render_part(boundary)
        end)
      end)

    Enum.join(parts) <> "--#{boundary}--\r\n"
  end

  # A value wrapped by ValueSerializer.encoded_part/3 carries the part
  # Content-Type and part headers its Encoding Object declares.
  defp part_encoding({:encoded_part, value, content_type, headers}),
    do: {value, {content_type, headers}}

  defp part_encoding(value), do: {value, {nil, []}}

  # The declared Content-Type replaces the one the part would get (a text part
  # that had none gains it); the declared headers follow it in order.
  defp apply_part_encoding({disposition, content_type, content}, {declared, headers}) do
    {disposition, declared || content_type, headers, content}
  end

  defp render_part({disposition, content_type, headers, content}, boundary) do
    type_line =
      if content_type, do: "Content-Type: #{part_header_text(content_type)}\r\n", else: ""

    header_lines =
      Enum.map_join(headers, fn {name, value} ->
        "#{part_header_text(name)}: #{part_header_text(value)}\r\n"
      end)

    "--#{boundary}\r\n#{disposition}\r\n#{type_line}#{header_lines}\r\n#{content}\r\n"
  end

  defp part_header_text(text) do
    text = to_string(text)

    if String.contains?(text, ["\r", "\n", <<0>>]) do
      raise ArgumentError,
            "multipart part header must not contain CR, LF or NUL characters (got: #{inspect(text)})"
    end

    text
  end

  # Each part is `{content_disposition, content_type_or_nil, content}`.
  defp multipart_part(name, {:file, filename, content}) do
    multipart_file_part(name, filename, content, nil)
  end

  defp multipart_part(name, {:file, filename, content, content_type}) do
    multipart_file_part(name, filename, content, content_type)
  end

  # A raw-bytes part carries binary content with no explicit filename. The
  # cross-language contract (go/node/java) reuses the field name as the
  # filename and derives the Content-Type from that name's extension,
  # falling back to application/octet-stream when there is none.
  defp multipart_part(name, {:raw, content}) do
    multipart_file_part(name, to_string(name), content, nil)
  end

  defp multipart_part(name, value) when is_binary(value) do
    {text_disposition(name), nil, value}
  end

  # A date, date-time, time or duration is a primitive: a plain text part in
  # the canonical stringify form, like a boolean, number or enum, with no part
  # Content-Type. Only an object/model/map is an application/json part.
  defp multipart_part(name, %struct{} = value)
       when struct in [DateTime, NaiveDateTime, Date, Time, Duration] do
    multipart_text_part(name, value)
  end

  defp multipart_part(name, value) when is_map(value) do
    {text_disposition(name), "application/json", PetstoreClient.ObjectSerializer.serialize(value)}
  end

  defp multipart_part(name, value), do: multipart_text_part(name, value)

  defp multipart_text_part(name, value) do
    {text_disposition(name), nil, PetstoreClient.ObjectSerializer.stringify(value)}
  end

  defp text_disposition(name),
    do: "Content-Disposition: form-data; name=\"#{sanitize_multipart_field_name(name)}\""

  # Validate/escape a multipart form field name before
  # interpolating it into a Content-Disposition header. Rejects
  # CR/LF/NUL (header-injection), and backslash-escapes a quote
  # and any backslash.
  defp sanitize_multipart_field_name(name) do
    str = to_string(name)

    if String.contains?(str, ["\r", "\n", <<0>>]) do
      raise ArgumentError,
            "multipart field name must not contain CR, LF or NUL characters (got: #{inspect(str)})"
    end

    escape_quoted(str)
  end

  defp multipart_file_part(name, filename, content, content_type) do
    {build_content_disposition(name, filename), content_type || guess_mime_type(filename),
     content}
  end

  @doc """
  Build a sanitized `Content-Disposition` header for a multipart file part.

  Validates the filename to prevent header injection (CRLF/NUL) and escapes
  `"` and `\\` inside the quoted ASCII fallback. When the filename contains
  non-ASCII characters, emits an RFC 5987 `filename*=UTF-8''<percent-encoded>`
  parameter alongside the sanitized ASCII `filename=` fallback.

  Raises `ArgumentError` when the filename contains `\\r`, `\\n`, or NUL.
  """
  @spec build_content_disposition(String.t(), String.t()) :: String.t()
  def build_content_disposition(name, filename) when is_binary(filename) do
    if String.contains?(filename, ["\r", "\n", <<0>>]) do
      raise ArgumentError,
            "multipart filename must not contain CR, LF, or NUL characters (got: #{inspect(filename)})"
    end

    # Validate the field name to reject CR/LF/NUL header
    # injection in addition to escaping embedded quotes / backslashes.
    escaped_name = sanitize_multipart_field_name(name)

    if ascii?(filename) do
      "Content-Disposition: form-data; name=\"#{escaped_name}\"; filename=\"#{escape_quoted(filename)}\""
    else
      ascii_fallback = filename |> to_ascii_fallback() |> escape_quoted()
      encoded = URI.encode(filename, &URI.char_unreserved?/1)

      "Content-Disposition: form-data; name=\"#{escaped_name}\"; " <>
        "filename=\"#{ascii_fallback}\"; filename*=UTF-8''#{encoded}"
    end
  end

  defp escape_quoted(value) do
    value
    |> String.replace("\\", "\\\\")
    |> String.replace("\"", "\\\"")
  end

  defp ascii?(binary) do
    :binary.bin_to_list(binary) |> Enum.all?(fn b -> b < 128 end)
  end

  # One `_` per Unicode code point that is non-ASCII or a control character, so
  # `résumé` becomes `r_sum_` and an emoji a single `_`, matching the other SDKs.
  defp to_ascii_fallback(filename) do
    filename
    |> String.codepoints()
    |> Enum.map_join(fn
      <<c>> when c in 32..126 -> <<c>>
      _ -> "_"
    end)
  end

  defp guess_mime_type(filename) when is_binary(filename) do
    if Code.ensure_loaded?(MIME) and function_exported?(MIME, :from_path, 1) do
      try do
        MIME.from_path(filename)
      rescue
        _ -> "application/octet-stream"
      end
    else
      "application/octet-stream"
    end
  end

  # Response header keys are normalised to lowercase so callers can
  # look them up consistently regardless of the casing the server used (HTTP
  # header names are case-insensitive per RFC 7230 section 3.2, and HTTP/2
  # mandates lowercase on the wire). Repeated header lines are joined with
  # ", " to preserve order per RFC 7230 section 3.2.2. The joined form is
  # not directly parseable for Set-Cookie; callers that need structured
  # cookie access should split on ", " with care or use a dedicated cookie
  # library such as `:cookies` or parse the original `Req.Response.headers/0`
  # map themselves.
  @doc false
  @spec normalize_headers(term()) :: %{optional(String.t()) => String.t()}
  def normalize_headers(headers) do
    Enum.reduce(headers, %{}, fn {key, values}, acc ->
      value =
        case values do
          list when is_list(list) -> Enum.join(list, ", ")
          v when is_binary(v) -> v
          _ -> to_string(values)
        end

      Map.put(acc, String.downcase(to_string(key)), value)
    end)
  end

  defp text_content_type?(content_type) do
    media_type =
      content_type
      |> String.split(";")
      |> List.first()
      |> String.trim()
      |> String.downcase()

    cond do
      media_type == "" -> true
      String.starts_with?(media_type, "text/") -> true
      media_type in ["application/json", "application/xml", "application/javascript"] -> true
      String.ends_with?(media_type, "+json") -> true
      String.ends_with?(media_type, "+xml") -> true
      true -> false
    end
  end

  @doc false
  # A URL for an error message: the query (where an API key may travel) and any
  # userinfo are dropped, so a credential never reaches a log.
  @spec redact_url(String.t()) :: String.t()
  def redact_url(url) do
    url
    |> URI.parse()
    |> Map.merge(%{query: nil, userinfo: nil, fragment: nil})
    |> URI.to_string()
  end

  # RFC 9110 section 5.1: header field names are case-insensitive, so a
  # caller's `user-agent` or `x-request-id` (even with an empty value) counts
  # as already set and is left exactly as written.
  defp has_header?(headers, name) do
    wanted = String.downcase(name, :ascii)
    Enum.any?(Map.keys(headers), &(String.downcase(to_string(&1), :ascii) == wanted))
  end

  # Later layer wins and keeps its own spelling: a header the caller passes
  # replaces a default of the same name whatever the casing, so one header is
  # never sent twice or chosen at random.
  defp merge_headers(base, overrides) do
    Enum.reduce(overrides, base, fn {name, value}, acc ->
      wanted = String.downcase(to_string(name), :ascii)

      acc
      |> Enum.reject(fn {key, _} -> String.downcase(to_string(key), :ascii) == wanted end)
      |> Map.new()
      |> Map.put(name, value)
    end)
  end

  defp generate_uuid do
    <<a::32, b::16, _::4, c::12, _::2, d::62>> = :crypto.strong_rand_bytes(16)

    :io_lib.format(
      "~8.16.0b-~4.16.0b-4~3.16.0b-~4.16.0b-~12.16.0b",
      [a, b, c &&& 0xFFF, (d >>> 48 &&& 0x3FFF) ||| 0x8000, d &&& 0xFFFFFFFFFFFF]
    )
    |> to_string()
  end
end
